using namespace std;

// 判断一个数是否为镜像数
bool isMirror(int num) {
    string s = to_string(num);
    string rev(s.rbegin(), s.rend());
    return s == rev;
}

int main() {
    int n;
    cin >> n;
    int k = 1;

    while (k * k <= n) {
        int p = n - k * k;
        if (isMirror(p)) {
            cout << "YES" << endl;
            cout << p << " " << (k * k) << endl;
            return 0;
        }
        k++;
    }
    cout << "NO" << endl;
    return 0;
}
